#:sdk Microsoft.NET.Sdk.Web #:package Microsoft.Kiota.Cli@1.0.0 #:package Microsoft.OpenApi.Readers@1.6.0 #:package System.Threading.Channels@8.0.0 #:property LangVersion=preview #:property TargetFramework=net10.0 #:property Nullable=enable #:property ImplicitUsings=enable  using System.Threading.Channels; using Microsoft.OpenApi.Models;  var builder = WebApplication.CreateBuilder();  // 动态加载通道 var specChannel = Channel.CreateBounded<OpenApiDocument>(     new BoundedChannelOptions(10000)     {         SingleReader = true,         AllowSynchronousContinuations = true     });  // 零拷贝加载器 builder.Services.AddSingleton<IOpenApiLoader>(sp =>      new ChannelOpenApiLoader(         specChannel,         new ThreadLocal<Span<byte>>(() => stackalloc byte[1024])));  var app = builder.Build(); app.MapGet("/", () => "OpenAPI Loader Ready"); app.Run();  [SkipLocalsInit] public class ChannelOpenApiLoader : IOpenApiLoader {     [MethodImpl(MethodImplOptions.AggressiveOptimization)]     public unsafe void Load(string specUrl)     {         Span<byte> buffer = stackalloc byte[1024];         fixed (byte* ptr = buffer)         {             if ((long)ptr % 64 == 0) // Cache-line对齐             {                 // SIMD优化处理OpenAPI规范             }         }     } }
